INSERT INTO collection_pages VALUES('4e8c184d7924532353eccdb8e659f6f733df532e8be0e6be2cc5618b0a4bdfc3','4e3db4f7cdbb17d35be0e3f086bd5965a4c3b04600777cb769c9b19215c8247e','{"hasNext":false,"items":[{"author":{"account":null,"email":"info@tbprojects.pl","name":"tbprojects"},"authoredDate":"2026-08-26T12:12:51Z","committedDate":"2026-08-26T12:12:51Z","committer":{"account":null,"email":"info@tbprojects.pl","name":"tbprojects"},"observedAt":"2026-10-09T00:23:20.703Z","repositoryId":1347305767,"sha":"62aa5f82cbe8c987b906fe311f61baf140cde320"},{"author":{"account":null,"email":"info@tbprojects.pl","name":"tbprojects"},"authoredDate":"2026-08-23T07:02:49Z","committedDate":"2026-08-23T07:02:49Z","committer":{"account":null,"email":"info@tbprojects.pl","name":"tbprojects"},"observedAt":"2026-10-09T00:23:20.703Z","repositoryId":1347305767,"sha":"ce63cd0c25b30c5816659902ac430ab8aedfb8c7"}],"observedAt":"2026-10-09T00:23:20.703Z","raw":[{"author":null,"comments_url":"https://api.github.com/repos/tbprojects/stream-deck-bestway/commits/62aa5f82cbe8c987b906fe311f61baf140cde320/comments","commit":{"author":{"date":"2026-08-26T12:12:51Z","email":"info@tbprojects.pl","name":"tbprojects"},"comment_count":0,"committer":{"date":"2026-08-26T12:12:51Z","email":"info@tbprojects.pl","name":"tbprojects"},"message":"fix(icons): make list icons white and resize the set to Marketplace spec\n\nThe Marketplace review rejected the submission because the action icon was\ncoloured. Both icons the Stream Deck app shows in its lists are now pure\n#FFFFFF on transparency, at the sizes the manifest schema states:\n\n- action-icon    20/40 px, white   (was 72/144 px, coloured)\n- category-icon  28/56 px, white   (redrawn from vector; was jagged at 28 px)\n- plugin-icon    256/512 px        (was 72/144 px — undersized, unreported)\n- key-icon       72/144 px, new    (the old action artwork)\n\nIcon and States[].Image pointed at the same file, which cannot hold for a\nwhite 20 px list icon and a coloured 72 px key image, so they are split.\n\nbuild-plugin-icons.py renders the whole set from vector sources so the sizes\nand colours cannot drift again; README documents the requirements.\n\nVersion bumped to 1.0.1.0 — Maker Console will not take the same one twice.\n\nCo-Authored-By: Claude Opus 5 <noreply@anthropic.com>\nClaude-Session: https://claude.ai/code/session_01CPsh39F4x3iQKDAPhzhRUK","tree":{"sha":"17a1cfb4ca886ed2aef7e21a382ea0f23d7a097a","url":"https://api.github.com/repos/tbprojects/stream-deck-bestway/git/trees/17a1cfb4ca886ed2aef7e21a382ea0f23d7a097a"},"url":"https://api.github.com/repos/tbprojects/stream-deck-bestway/git/commits/62aa5f82cbe8c987b906fe311f61baf140cde320","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/tbprojects/stream-deck-bestway/commit/62aa5f82cbe8c987b906fe311f61baf140cde320","node_id":"C_kwDOUE5BJ9oAKDYyYWE1ZjgyY2JlOGM5ODdiOTA2ZmUzMTFmNjFiYWYxNDBjZGUzMjA","parents":[{"html_url":"https://github.com/tbprojects/stream-deck-bestway/commit/ce63cd0c25b30c5816659902ac430ab8aedfb8c7","sha":"ce63cd0c25b30c5816659902ac430ab8aedfb8c7","url":"https://api.github.com/repos/tbprojects/stream-deck-bestway/commits/ce63cd0c25b30c5816659902ac430ab8aedfb8c7"}],"sha":"62aa5f82cbe8c987b906fe311f61baf140cde320","url":"https://api.github.com/repos/tbprojects/stream-deck-bestway/commits/62aa5f82cbe8c987b906fe311f61baf140cde320"},{"author":null,"comments_url":"https://api.github.com/repos/tbprojects/stream-deck-bestway/commits/ce63cd0c25b30c5816659902ac430ab8aedfb8c7/comments","commit":{"author":{"date":"2026-08-23T07:02:49Z","email":"info@tbprojects.pl","name":"tbprojects"},"comment_count":0,"committer":{"date":"2026-08-23T07:02:49Z","email":"info@tbprojects.pl","name":"tbprojects"},"message":"chore: initial version\n\nStream Deck plugin for a Bestway Lay-Z-Spa: water temperature and heater\nstate on the key, the running functions on a short press, and a heater\ntoggle on a long press.\n\nTalks to the SmartSpa gateway (smart-spa-{eu,us,cn}-app.bestwaycorp.com),\nwhich is where Bestway moved V02 devices in the app update of late July\n2026. Signs in with account credentials and then discards the password,\nkeeping only the session token the gateway issues.\n\nCo-Authored-By: Claude Opus 5 <noreply@anthropic.com>\nClaude-Session: https://claude.ai/code/session_01CtMWQqf1uUW2n8yZMz9rSq","tree":{"sha":"2220fdb0829a1c8c4a3297d5af9b3cb824a08b4f","url":"https://api.github.com/repos/tbprojects/stream-deck-bestway/git/trees/2220fdb0829a1c8c4a3297d5af9b3cb824a08b4f"},"url":"https://api.github.com/repos/tbprojects/stream-deck-bestway/git/commits/ce63cd0c25b30c5816659902ac430ab8aedfb8c7","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/tbprojects/stream-deck-bestway/commit/ce63cd0c25b30c5816659902ac430ab8aedfb8c7","node_id":"C_kwDOUE5BJ9oAKGNlNjNjZDBjMjViMzBjNTgxNjY1OTkwMmFjNDMwYWI4YWVkZmI4Yzc","parents":[],"sha":"ce63cd0c25b30c5816659902ac430ab8aedfb8c7","url":"https://api.github.com/repos/tbprojects/stream-deck-bestway/commits/ce63cd0c25b30c5816659902ac430ab8aedfb8c7"}],"requestUrl":"https://api.github.com/repos/tbprojects/stream-deck-bestway/commits?per_page=100&page=1&sha=62aa5f82cbe8c987b906fe311f61baf140cde320&since=2025-03-31T23%3A59%3A59.000Z&until=2026-10-08T16%3A21%3A58.017Z"}');
