op @-referenced env block from vercel.json for clean Vercel deploy","tree":{"sha":"4e9e8c443eb6b28ef2e7efb2b6b92ca7a473f443","url":"https://api.github.com/repos/zyj020701/team-portal-lite2/git/trees/4e9e8c443eb6b28ef2e7efb2b6b92ca7a473f443"},"url":"https://api.github.com/repos/zyj020701/team-portal-lite2/git/commits/8d819ec403e7288967af8af1a3959b58a1761edf","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/308586207?v=4","events_url":"https://api.github.com/users/zyj020701/events{/privacy}","followers_url":"https://api.github.com/users/zyj020701/followers","following_url":"https://api.github.com/users/zyj020701/following{/other_user}","gists_url":"https://api.github.com/users/zyj020701/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/zyj020701","id":308586207,"login":"zyj020701","node_id":"U_kgDOEmSm3w","organizations_url":"https://api.github.com/users/zyj020701/orgs","received_events_url":"https://api.github.com/users/zyj020701/received_events","repos_url":"https://api.github.com/users/zyj020701/repos","site_admin":false,"starred_url":"https://api.github.com/users/zyj020701/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/zyj020701/subscriptions","type":"User","url":"https://api.github.com/users/zyj020701","user_view_type":"public"},"html_url":"https://github.com/zyj020701/team-portal-lite2/commit/8d819ec403e7288967af8af1a3959b58a1761edf","node_id":"C_kwDOUFgFCNoAKDhkODE5ZWM0MDNlNzI4ODk2N2FmOGFmMWEzOTU5YjU4YTE3NjFlZGY","parents":[{"html_url":"https://github.com/zyj020701/team-portal-lite2/commit/100d93b72650ab12160b4d736c111f1552b19b74","sha":"100d93b72650ab12160b4d736c111f1552b19b74","url":"https://api.github.com/repos/zyj020701/team-portal-lite2/commits/100d93b72650ab12160b4d736c111f1552b19b74"}],"sha":"8d819ec403e7288967af8af1a3959b58a1761edf","url":"https://api.github.com/repos/zyj020701/team-portal-