INSERT INTO collection_pages VALUES('51e277a6be8c03de00b9d237d54ebc441e0183c5b878003953d961e28cb7f989','51ec2032f4333f7ed97eb7463b1ae149e861ca0f5f72e8f6254c97c208d035a6','{"hasNext":false,"items":[{"author":{"account":null,"email":"romuald.marin@france-bioinformatique.fr","name":"Romuald.marin"},"authoredDate":"2026-09-01T10:00:23Z","committedDate":"2026-09-01T10:00:23Z","committer":{"account":null,"email":"romuald.marin@france-bioinformatique.fr","name":"Romuald.marin"},"observedAt":"2026-10-09T00:24:17.330Z","repositoryId":1348455441,"sha":"f282f1e135a33cae42e7512a85267a95466489a9"},{"author":{"account":null,"email":"romuald.marin@france-bioinformatique.fr","name":"Romuald.marin"},"authoredDate":"2026-09-01T09:35:16Z","committedDate":"2026-09-01T09:35:16Z","committer":{"account":null,"email":"romuald.marin@france-bioinformatique.fr","name":"Romuald.marin"},"observedAt":"2026-10-09T00:24:17.330Z","repositoryId":1348455441,"sha":"955f5df08a0a88f19047b4039b0fbb38c6130f9f"},{"author":{"account":null,"email":"romuald.marin@france-bioinformatique.fr","name":"Romuald.marin"},"authoredDate":"2026-09-01T08:54:09Z","committedDate":"2026-09-01T08:54:09Z","committer":{"account":null,"email":"romuald.marin@france-bioinformatique.fr","name":"Romuald.marin"},"observedAt":"2026-10-09T00:24:17.330Z","repositoryId":1348455441,"sha":"6ca65c153d2b9d4a91ad8e7b7af231b42f947420"},{"author":{"account":null,"email":"romuald.marin@france-bioinformatique.fr","name":"Romuald.marin"},"authoredDate":"2026-09-01T08:49:12Z","committedDate":"2026-09-01T08:49:12Z","committer":{"account":null,"email":"romuald.marin@france-bioinformatique.fr","name":"Romuald.marin"},"observedAt":"2026-10-09T00:24:17.330Z","repositoryId":1348455441,"sha":"4987aaae231f8e7aaec3c506266d10075d8faa16"},{"author":{"account":null,"email":"romuald.marin@france-bioinformatique.fr","name":"Romuald.marin"},"authoredDate":"2026-08-27T12:29:34Z","committedDate":"2026-08-27T12:29:34Z","committer":{"account":null,"email":"romuald.marin@france-bioinformatique.fr","name":"Romuald.marin"},"observedAt":"2026-10-09T00:24:17.330Z","repositoryId":1348455441,"sha":"00bcb3e02a4ef1050ea4f043fcba43a0fae9f742"},{"author":{"account":null,"email":"romuald.marin@france-bioinformatique.fr","name":"rmarin"},"authoredDate":"2026-08-27T12:17:28Z","committedDate":"2026-08-27T12:17:28Z","committer":{"account":null,"email":"romuald.marin@france-bioinformatique.fr","name":"rmarin"},"observedAt":"2026-10-09T00:24:17.330Z","repositoryId":1348455441,"sha":"23fc02c9fbaf8403bce29d1ffcd929c8812777a0"},{"author":{"account":null,"email":"romuald.marin@france-bioinformatique.fr","name":"Romuald.marin"},"authoredDate":"2026-08-27T11:58:16Z","committedDate":"2026-08-27T11:58:16Z","committer":{"account":null,"email":"romuald.marin@france-bioinformatique.fr","name":"Romuald.marin"},"observedAt":"2026-10-09T00:24:17.330Z","repositoryId":1348455441,"sha":"b688d4310a34fe461af11f50d4b6823e8baa7763"}],"observedAt":"2026-10-09T00:24:17.330Z","raw":[{"author":null,"comments_url":"https://api.github.com/repos/Romumrn/CatMatch/commits/f282f1e135a33cae42e7512a85267a95466489a9/comments","commit":{"author":{"date":"2026-09-01T10:00:23Z","email":"romuald.marin@france-bioinformatique.fr","name":"Romuald.marin"},"comment_count":0,"committer":{"date":"2026-09-01T10:00:23Z","email":"romuald.marin@france-bioinformatique.fr","name":"Romuald.marin"},"message":"Pluie d''emojis chats et ronronnement à chaque match\n\n- EmojiRain : 34 emojis chats tombent pendant 5 s, taille, dérive et\n  rotation aléatoires. Une seule valeur animée pilote l''ensemble, chaque\n  emoji lisant sa tranche via interpolate() — react-native-web n''a pas de\n  moteur natif, et animer 34 valeurs en JS fait chuter le framerate.\n  La pluie passe derrière la carte pour ne pas gêner la lecture.\n\n- Ronronnement synthétisé (assets/sounds/purr.mp3, 20 Ko) plutôt que\n  téléchargé : bruit blanc filtré passe-bas, modulé par un train\n  d''impulsions à 24-27 Hz avec cadence respirante, plus un corps grave.\n  Mesuré sur le fichier : cadence 25,1 Hz, 96 % de l''énergie sous 300 Hz.\n\n- SoundContext déverrouille l''audio au premier appui sur la page : un\n  match issu d''un swipe joue le son ~230 ms après le relâchement, dans le\n  callback d''animation, ce que Safari mobile refuse sans geste préalable.\n  Interrupteur « Ronronnement au match » dans le profil.\n\n- L''écran de match est extrait dans MatchCelebration et sert aussi quand\n  on rend un like depuis « Likes reçus », qui n''affichait rien avant.\n\nCo-Authored-By: Claude Opus 5 <noreply@anthropic.com>","tree":{"sha":"b4e7c3922ce4cc9b6241677bb0eec1140b444c9f","url":"https://api.github.com/repos/Romumrn/CatMatch/git/trees/b4e7c3922ce4cc9b6241677bb0eec1140b444c9f"},"url":"https://api.github.com/repos/Romumrn/CatMatch/git/commits/f282f1e135a33cae42e7512a85267a95466489a9","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/Romumrn/CatMatch/commit/f282f1e135a33cae42e7512a85267a95466489a9","node_id":"C_kwDOUF_MEdoAKGYyODJmMWUxMzVhMzNjYWU0MmU3NTEyYTg1MjY3YTk1NDY2NDg5YTk","parents":[{"html_url":"https://github.com/Romumrn/CatMatch/commit/955f5df08a0a88f19047b4039b0fbb38c6130f9f","sha":"955f5df08a0a88f19047b4039b0fbb38c6130f9f","url":"https://api.github.com/repos/Romumrn/CatMatch/commits/955f5df08a0a88f19047b4039b0fbb38c6130f9f"}],"sha":"f282f1e135a33cae42e7512a85267a95466489a9","url":"https://api.github.com/repos/Romumrn/CatMatch/commits/f282f1e135a33cae42e7512a85267a95466489a9"},{"author":null,"comments_url":"https://api.github.com/repos/Romumrn/CatMatch/commits/955f5df08a0a88f19047b4039b0fbb38c6130f9f/comments","commit":{"author":{"date":"2026-09-01T09:35:16Z","email":"romuald.marin@france-bioinformatique.fr","name":"Romuald.marin"},"comment_count":0,"committer":{"date":"2026-09-01T09:35:16Z","email":"romuald.marin@france-bioinformatique.fr","name":"Romuald.marin"},"message":"Refonte en vraie appli de rencontre : accueil swipe, lieux, contact masqué\n\nDemandes :\n- L''app s''ouvre sur le deck de swipe, plus sur le profil.\n- Nouveau critère « lieu de rencontre préféré », limité à trois valeurs :\n  Parc, Appartement, Cour d''immeuble. Présent sur les profils, dans les\n  filtres, et compte pour 30 % du score d''affinité.\n- Aucun numéro de téléphone en clair : maskPhone() ne garde que les deux\n  premiers et deux derniers chiffres (06 ** ** ** 78), partout, y compris\n  après un match et sur son propre profil.\n\nPasse qualité :\n- 4e onglet « Likes reçus » : qui a liké, photos floutées à révéler.\n- Super like (3/jour, swipe vers le haut) et retour arrière sur le\n  dernier swipe, avec restauration du deck et des compteurs.\n- Écran Filtres : distance, âge, sexe, lieu, tempérament, vérifiés.\n- Score d''affinité (tempéraments 50 %, lieux 30 %, proximité 20 %) affiché\n  sur la carte, la fiche et l''écran de match.\n- Fiche profil : carrousel photo, race, santé, correspondances surlignées,\n  signalement. Chat : séparateurs de date, accusés de lecture, indicateur\n  de frappe, dématcher. Profil : jauge de complétion, santé, contact.\n- Profils vérifiés, présence en ligne, états vides avec appel à l''action.\n\nPhotos de démo embarquées dans assets/demo/ : le lien externe « george »\nrenvoyait un 404 et affichait une vignette grise. Le site publié ne dépend\nplus d''un service tiers pour ses images.\n\nCo-Authored-By: Claude Opus 5 <noreply@anthropic.com>","tree":{"sha":"9ced0550d00923aa2c733d31acb2c2b876434faa","url":"https://api.github.com/repos/Romumrn/CatMatch/git/trees/9ced0550d00923aa2c733d31acb2c2b876434faa"},"url":"https://api.github.com/repos/Romumrn/CatMatch/git/commits/955f5df08a0a88f19047b4039b0fbb38c6130f9f","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/Romumrn/CatMatch/commit/955f5df08a0a88f19047b4039b0fbb38c6130f9f","node_id":"C_kwDOUF_MEdoAKDk1NWY1ZGYwOGEwYTg4ZjE5MDQ3YjQwMzliMGZiYjM4YzYxMzBmOWY","parents":[{"html_url":"https://github.com/Romumrn/CatMatch/commit/6ca65c153d2b9d4a91ad8e7b7af231b42f947420","sha":"6ca65c153d2b9d4a91ad8e7b7af231b42f947420","url":"https://api.github.com/repos/Romumrn/CatMatch/commits/6ca65c153d2b9d4a91ad8e7b7af231b42f947420"}],"sha":"955f5df08a0a88f19047b4039b0fbb38c6130f9f","url":"https://api.github.com/repos/Romumrn/CatMatch/commits/955f5df08a0a88f19047b4039b0fbb38c6130f9f"},{"author":null,"comments_url":"https://api.github.com/repos/Romumrn/CatMatch/commits/6ca65c153d2b9d4a91ad8e7b7af231b42f947420/comments","commit":{"author":{"date":"2026-09-01T08:54:09Z","email":"romuald.marin@france-bioinformatique.fr","name":"Romuald.marin"},"comment_count":0,"committer":{"date":"2026-09-01T08:54:09Z","email":"romuald.marin@france-bioinformatique.fr","name":"Romuald.marin"},"message":"Corrige le déploiement web : polices d''icônes absentes de gh-pages\n\nLe paquet `gh-pages` publie via un `git add` classique : le .gitignore du\ndépôt (`node_modules/`) écartait silencieusement les 30 fichiers de\ndist/assets/node_modules/**, soit toutes les polices @expo/vector-icons.\nEn ligne, toutes les icônes s''affichaient en carrés vides.\n\nRemplacé par scripts/deploy-web.sh, qui publie dist/ dans un worktree git\nsur gh-pages avec `git add -f` et écrit .nojekyll. 45 fichiers publiés\nau lieu de 15.\n\nCo-Authored-By: Claude Opus 5 <noreply@anthropic.com>","tree":{"sha":"241dc3e855a031021415d091e36d414519713522","url":"https://api.github.com/repos/Romumrn/CatMatch/git/trees/241dc3e855a031021415d091e36d414519713522"},"url":"https://api.github.com/repos/Romumrn/CatMatch/git/commits/6ca65c153d2b9d4a91ad8e7b7af231b42f947420","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/Romumrn/CatMatch/commit/6ca65c153d2b9d4a91ad8e7b7af231b42f947420","node_id":"C_kwDOUF_MEdoAKDZjYTY1YzE1M2QyYjlkNGE5MWFkOGU3YjdhZjIzMWI0MmY5NDc0MjA","parents":[{"html_url":"https://github.com/Romumrn/CatMatch/commit/4987aaae231f8e7aaec3c506266d10075d8faa16","sha":"4987aaae231f8e7aaec3c506266d10075d8faa16","url":"https://api.github.com/repos/Romumrn/CatMatch/commits/4987aaae231f8e7aaec3c506266d10075d8faa16"}],"sha":"6ca65c153d2b9d4a91ad8e7b7af231b42f947420","url":"https://api.github.com/repos/Romumrn/CatMatch/commits/6ca65c153d2b9d4a91ad8e7b7af231b42f947420"},{"author":null,"comments_url":"https://api.github.com/repos/Romumrn/CatMatch/commits/4987aaae231f8e7aaec3c506266d10075d8faa16/comments","commit":{"author":{"date":"2026-09-01T08:49:12Z","email":"romuald.marin@france-bioinformatique.fr","name":"Romuald.marin"},"comment_count":0,"committer":{"date":"2026-09-01T08:49:12Z","email":"romuald.marin@france-bioinformatique.fr","name":"Romuald.marin"},"message":"Version web GitHub Pages + profil de Richard à l''ouverture\n\n- app.json : export web statique sous le sous-chemin /CatMatch\n  (experiments.baseUrl + web.output \"single\"), métadonnées PWA.\n- App.tsx : l''app démarre sur l''onglet Profil.\n- ProfileScreen : photo principale + galerie horizontale des photos de\n  Richard, lightbox plein écran, largeur bornée pour le web desktop.\n- AppContext/types : le profil accepte des images locales (require) et\n  une galerie ; profil de Richard, 2 ans, joueur/sociable/timide.\n- SwipeDeck : carte bornée à 480 px pour ne pas s''étaler sur desktop.\n- README : présentation façon App Store + captures d''écran, procédure\n  de déploiement GitHub Pages.\n- Scripts build:web / predeploy / deploy (gh-pages --nojekyll).\n\nCo-Authored-By: Claude Opus 5 <noreply@anthropic.com>","tree":{"sha":"55f0bb9a5ca7e0096e5ded3dd63db29b42f86d9e","url":"https://api.github.com/repos/Romumrn/CatMatch/git/trees/55f0bb9a5ca7e0096e5ded3dd63db29b42f86d9e"},"url":"https://api.github.com/repos/Romumrn/CatMatch/git/commits/4987aaae231f8e7aaec3c506266d10075d8faa16","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/Romumrn/CatMatch/commit/4987aaae231f8e7aaec3c506266d10075d8faa16","node_id":"C_kwDOUF_MEdoAKDQ5ODdhYWFlMjMxZjhlN2FhZWMzYzUwNjI2NmQxMDA3NWQ4ZmFhMTY","parents":[{"html_url":"https://github.com/Romumrn/CatMatch/commit/00bcb3e02a4ef1050ea4f043fcba43a0fae9f742","sha":"00bcb3e02a4ef1050ea4f043fcba43a0fae9f742","url":"https://api.github.com/repos/Romumrn/CatMatch/commits/00bcb3e02a4ef1050ea4f043fcba43a0fae9f742"}],"sha":"4987aaae231f8e7aaec3c506266d10075d8faa16","url":"https://api.github.com/repos/Romumrn/CatMatch/commits/4987aaae231f8e7aaec3c506266d10075d8faa16"},{"author":null,"comments_url":"https://api.github.com/repos/Romumrn/CatMatch/commits/00bcb3e02a4ef1050ea4f043fcba43a0fae9f742/comments","commit":{"author":{"date":"2026-08-27T12:29:34Z","email":"romuald.marin@france-bioinformatique.fr","name":"Romuald.marin"},"comment_count":0,"committer":{"date":"2026-08-27T12:29:34Z","email":"romuald.marin@france-bioinformatique.fr","name":"Romuald.marin"},"message":"Rétrogradation vers Expo SDK 54 pour compatibilité Expo Go\n\nCo-Authored-By: Claude Fable 5 <noreply@anthropic.com>","tree":{"sha":"32b6ca7227c0e7519a545592645e2a42c792985e","url":"https://api.github.com/repos/Romumrn/CatMatch/git/trees/32b6ca7227c0e7519a545592645e2a42c792985e"},"url":"https://api.github.com/repos/Romumrn/CatMatch/git/commits/00bcb3e02a4ef1050ea4f043fcba43a0fae9f742","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/Romumrn/CatMatch/commit/00bcb3e02a4ef1050ea4f043fcba43a0fae9f742","node_id":"C_kwDOUF_MEdoAKDAwYmNiM2UwMmE0ZWYxMDUwZWE0ZjA0M2ZjYmE0M2EwZmFlOWY3NDI","parents":[{"html_url":"https://github.com/Romumrn/CatMatch/commit/23fc02c9fbaf8403bce29d1ffcd929c8812777a0","sha":"23fc02c9fbaf8403bce29d1ffcd929c8812777a0","url":"https://api.github.com/repos/Romumrn/CatMatch/commits/23fc02c9fbaf8403b